/bin/zsh -lc "cat > tb.sv <<'EOF'
module tb;
  reg clk = 0;
  reg rst_n = 0;
  wire [5:0] second;
  wire [5:0] minute;

  TopModule dut(.clk(clk), .rst_n(rst_n), .second(second), .minute(minute));

  always #5 clk = ~clk;

  integer i;
  initial begin
    #2;
    if (second "'!== 0 || minute !== 0) begin
      $display("FAIL reset values: m=%0d s=%0d", minute, second);
      $finish(1);
    end
    rst_n = 1;

    @(posedge clk);
    #1;
    if (second !== 1 || minute !== 0) begin
      $display("FAIL first tick: m=%0d s=%0d", minute, second);
      $finish(1);
    end

    repeat (59) @(posedge clk);
    #1;
    if (second !== 60 || minute !== 0) begin
      $display("FAIL before rollover: m=%0d s=%0d", minute, second);
      $finish(1);
    end

    @(posedge clk);
    #1;
    if (second !== 1 || minute !== 1) begin
      $display("FAIL first rollover: m=%0d s=%0d", minute, second);
      $finish(1);
    end

    repeat (59*60) @(posedge clk);
    #1;
    if (minute !== 60 || second !== 1) begin
      $display("FAIL reach max minute: m=%0d s=%0d", minute, second);
      $finish(1);
    end

    repeat (3) @(posedge clk);
    #1;
    if (minute !== 60 || second !== 1) begin
      $display("FAIL pause at max minute: m=%0d s=%0d", minute, second);
      $finish(1);
    end

    $display("PASS");
    $finish;
  end
endmodule
EOF
iverilog -g2012 -o simv tb.sv TopModule.sv && vvp simv'

